"use client";

import React, { useState, useRef } from "react";
import { motion, useMotionValue, useSpring } from "motion/react";
import { cn } from "@/lib/utils";

export interface IosPointerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
}

export function IosPointerContainer({
  children,
  className,
  ...props
}: IosPointerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHoveringTarget, setIsHoveringTarget] = useState(false);
  const [isInside, setIsInside] = useState(false);

  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const springConfig = { damping: 28, stiffness: 450, mass: 0.5 };
  const cursorX = useSpring(mouseX, springConfig);
  const cursorY = useSpring(mouseY, springConfig);

  const cursorWidth = useSpring(18, springConfig);
  const cursorHeight = useSpring(18, springConfig);
  const cursorRadius = useSpring(9, springConfig);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const containerRect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - containerRect.left;
    const y = e.clientY - containerRect.top;

    mouseX.set(x);
    mouseY.set(y);

    const target = (e.target as HTMLElement).closest("[data-magnetic-target]");
    if (target && containerRef.current.contains(target)) {
      const rect = target.getBoundingClientRect();
      const relativeRect = {
        left: rect.left - containerRect.left,
        top: rect.top - containerRect.top,
        width: rect.width,
        height: rect.height,
      };

      setIsHoveringTarget(true);

      // Magnetically snap to center of the target button
      mouseX.set(relativeRect.left + relativeRect.width / 2);
      mouseY.set(relativeRect.top + relativeRect.height / 2);
      cursorWidth.set(relativeRect.width + 8);
      cursorHeight.set(relativeRect.height + 8);
      cursorRadius.set(16);
    } else {
      setIsHoveringTarget(false);
      cursorWidth.set(18);
      cursorHeight.set(18);
      cursorRadius.set(9);
    }
  };

  return (
    <div
      ref={containerRef}
      data-slot="ios-pointer"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsInside(true)}
      onMouseLeave={() => {
        setIsInside(false);
        setIsHoveringTarget(false);
      }}
      className={cn("relative overflow-hidden cursor-none select-none", className)}
      {...props}
    >
      {children}

      {/* iPadOS / iOS Pointer Dot */}
      {isInside ? (
        <motion.div
          style={{
            x: cursorX,
            y: cursorY,
            width: cursorWidth,
            height: cursorHeight,
            borderRadius: cursorRadius,
            translateX: "-50%",
            translateY: "-50%",
          }}
          className={cn(
            "pointer-events-none absolute z-50 transition-colors duration-200",
            isHoveringTarget
              ? "bg-black/10 dark:bg-white/15 backdrop-blur-[2px] border border-black/10 dark:border-white/20"
              : "bg-neutral-800/80 dark:bg-neutral-200/80 shadow-md backdrop-invert-0"
          )}
        />
      ) : null}
    </div>
  );
}

export function IosMagneticButton({
  children,
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      data-magnetic-target="true"
      type="button"
      className={cn(
        "relative rounded-xl px-5 py-2.5 text-sm font-semibold transition-transform active:scale-95 focus-visible:outline-none",
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
}
